sys_script_include.script:
var GRCOpsUtils = Class.create();
GRCOpsUtils.prototype = {
    initialize: function() {},

    /**
     * Function to fetch list of users who are a part of GRC Ops App
     * return - query to fetch list of targeted users which will be queried on sys_user table
     */
    fetchGRCOpsAppUsers: function() {
        var gr = new GlideRecord("sys_user_grmember");
        gr.addEncodedQuery("group.nameSTARTSWITHGRC^user.last_nameNOT LIKE(Dev)");
        gr.query();
        var list = new Set();
        while (gr.next()) {
            list.add(gr.user.sys_id.toString());
        }
        var uniqueList = [];
        list.forEach(function(value) {
            uniqueList.push(value);
        });
        return 'sys_idIN' + uniqueList.join(',');
    },

    /**
     * Function to return list of users to be used in Ref Qual POD Contributors Field
     * in the Accelerators table.
     * return - query to fetch list of targeted users based on Accelerator Type Selected. If Type = POD Based, returns list of POD members of the selected Employee, Else, returns list of users scoped under Ops App.
     */
    queryBuildForContributors: function(current) {
        var uniqueList = [];
        var resultQuery = '';

        if (current.accelerator_type == 'pod_based') {
            var gr = new GlideRecord("sys_user_grmember");
            gr.addEncodedQuery('user.sys_id=' + current.resource + '^group.nameSTARTSWITHPOD');
            gr.query();
            if (gr.next()) {
                var gr2 = new GlideRecord("sys_user_grmember");
                gr2.addEncodedQuery('group.sys_id=' + gr.group.sys_id);
                gr2.query();
                while (gr2.next())
                    uniqueList.push(gr2.user.sys_id.toString());
            }
            resultQuery = 'sys_idIN' + uniqueList.join(',');
        } else if (current.accelerator_type == 'self_built')
            resultQuery = this.fetchGRCOpsAppUsers();
        else
            resultQuery = 'sys_idIN';

        return resultQuery;
    },

    /**
     * Function to return list of users to be used in Ref Qual POD Contributors Field
     * in the Accelerators table.
     * return - query to fetch list of targeted users based on Accelerator Type Selected. If Type = POD Based, returns list of POD members of the selected Employee, Else, returns list of users scoped under Ops App.
     */
    queryBuildForContributorsPortal: function(selectedType) {
        var uniqueList = [];
        var resultQuery = '';
        var currentUser = gs.getUserID();
        if (selectedType == 'pod') {
            var gr = new GlideRecord("sys_user_grmember");
            gr.addEncodedQuery('user.sys_id=' + currentUser + '^group.nameSTARTSWITHPOD');
            gr.query();
            if (gr.next()) {
                var gr2 = new GlideRecord("sys_user_grmember");
                gr2.addEncodedQuery('group.sys_id=' + gr.group.sys_id);
                gr2.query();
                while (gr2.next())
                    uniqueList.push(gr2.user.sys_id.toString());
            }
            resultQuery = 'sys_idIN' + uniqueList.join(',');
        } else if (selectedType == 'self')
            resultQuery = this.fetchGRCOpsAppUsers();
        else
            resultQuery = 'sys_idIN';

        return resultQuery;
    },

    /**
     * Function to fetch list of users who are a part of GRC Ops App
     * return - query to fetch list of targeted users which will be queried on sys_user table
     */
    fetchPODMembers: function(currentGrp) {
        var currentGrpUser = new GlideRecord('sys_user_grmember');
        currentGrpUser.addQuery('group', currentGrp.sys_id);
        currentGrpUser.query();
        var list = new Set();
        while (currentGrpUser.next()) {
            list.add(currentGrpUser.user.sys_id.toString());
        }
        var uniqueList = [];
        list.forEach(function(value) {
            uniqueList.push(value);
        });
        return 'sys_idIN' + uniqueList.join(',');
    },


	/**
	 * Function to calculate number of days due from current date to a specified reference date
	 * return - number of days in string
	 */
    anniversaryDaysDueCalculation: function(referenceDate) {
        if (referenceDate) {
            var today = new GlideDate();
            var bday = new GlideDate();
            bday.setValue(referenceDate);

            // Get current year
            var currentYear = today.getYearUTC();

            // Set birthday to current year
            var nextBday = new GlideDate();
            nextBday.setYearUTC(currentYear);
            nextBday.setMonthUTC(bday.getMonthUTC());
            nextBday.setDayOfMonthUTC(bday.getDayOfMonthUTC());

            // If birthday has passed this year, look at next year
            if (nextBday.getNumericValue() < today.getNumericValue()) {
                nextBday.addYears(1);
            }

            // Calculate difference
            var diffMs = nextBday.getNumericValue() - today.getNumericValue();
            var daysLeft = Math.floor(diffMs / (1000 * 60 * 60 * 24));

            return daysLeft.toString() + " days";
        }
        return "unknown";
    },

    type: 'GRCOpsUtils'
};
